code.source:
class Animal:
    def speak(self):
        return "..."

class Dog(Animal):
    def speak(self):
        return "Woof"

class Fish(Animal):
    pass

print(Animal().speak())
print(Dog().speak())
print(Fish().speak())

class Greeter:
    def greet(self):
        return "Hello"

class LoudGreeter(Greeter):
    def greet(self):
        base = super().greet()
        return base.upper() + "!"

print(Greeter().greet())
print(LoudGreeter().greet())

